//! Full-run parity on further Eunomia datasets (generated by `tests/oracle/eunomia-cases.R`).
//!
//! The installed Eunomia 2.1.0 offers GiBleed (covered by `tests/parity.rs`), MIMIC (CDM 5.3),
//! Synthea27Nj (CDM 5.4), and a Parquet copy of Synthea27Nj. Each dataset runs every default
//! check on SQLite. The datasets run one after another in a single test, so their SQLite
//! temporary files (about 1 GB at peak on MIMIC) never add up.
//!
//! Regenerate one dataset's oracle (about 3 minutes each) with the `scripts/parity.ps1`
//! environment, from a database built by `Eunomia::getDatabaseFile(name, cdmVersion, dbms = "sqlite")`:
//! `Rscript --vanilla tests/oracle/eunomia-cases.R <upstream> <MIMIC_5.3.sqlite> tests/oracle/generated/eunomia/mimic 1 MIMIC 5.3`
//! (and `... synthea27nj 1 Synthea27Nj 5.4` for Synthea27Nj).
use data_quality_dashboard::model::Options;
use serde_json::Value;
use std::fs;

mod common;
use common::*;

const DATASETS: [&str; 2] = ["synthea27nj", "mimic"];

#[test]
fn eunomia_dataset_runs_match_upstream_results_and_csv() {
    for name in DATASETS {
        let folder = oracle().join("eunomia").join(name);
        let expected = read_json(&folder.join("results.json"));
        let timing = read_json(&folder.join("timing.json"));
        assert_eq!(
            timing["status_counts"]["error"], 0,
            "{name}: oracle run had SQL errors"
        );
        // A full disk during the R run shows up only as a warning on the affected rows.
        let contaminated: Vec<&Value> = expected["CheckResults"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|row| !row["warning"].is_null() || !row["error"].is_null())
            .collect();
        assert!(
            contaminated.is_empty(),
            "{name}: regenerate the oracle, rows carry warnings or errors: {contaminated:?}"
        );
        let mut options: Options =
            serde_json::from_value(read_json(&folder.join("options.json"))).expect("options");
        let temporary = tempfile::tempdir().unwrap();
        let working = temporary.path().join("cdm.sqlite");
        fs::copy(folder.join("cdm.sqlite"), &working).unwrap();
        options.dbms = "sqlite".into();
        options.connection.sqlite_path = Some(working);
        options.output_folder = temporary.path().join("results");
        let actual = run_and_read_results_file(name, &options);
        assert_eq!(
            expected["CheckResults"].as_array().unwrap().len(),
            timing["total_checks"].as_u64().unwrap() as usize,
            "{name}: oracle check count"
        );
        assert_results_match(name, &actual, &expected);
        let actual_csv = fs::read_to_string(options.output_folder.join(&options.csv_file)).unwrap();
        let expected_csv = fs::read_to_string(folder.join(&options.csv_file)).unwrap();
        assert_eq!(
            csv_records(&actual_csv),
            csv_records(&expected_csv),
            "{name} CSV"
        );
    }
}
